    private final HybridLogicalClock clock;
    private final KafkaTemplate<String, HLCValue> template;
    @CircuitBreaker(name = "hlcPub", fallbackMethod = "fallback")
    public void publish(String key) {
        HLCValue ts = clock.now();
        template.send("hlc-topic", key, ts);
    }
