```

```java
@RestController
@RequestMapping("/kv")
public class KvController {

    private final HybridLogicalClock hlc;
    private final GCounter counter;
    private final LWWRegister<String> register;

    public KvController(HybridLogicalClock hlc, GCounter counter, LWWRegister<String> register) {
        this.hlc = hlc;
        this.counter = counter;
        this.register = register;
    }

    @PostMapping("/inc")
    public ResponseEntity<Long> inc(@RequestParam String node, @RequestParam long delta) {
        counter.increment(node, delta);
        return ResponseEntity.ok(counter.value());
    }

    @PostMapping("/write")
    public ResponseEntity<Void> write(@RequestBody String value) {
        register.write(value, hlc.now());
        return ResponseEntity.ok().build();
    }

    @GetMapping("/read")
    public ResponseEntity<String> read() { return ResponseEntity.ok(register.read()); }
}
```

