| Problem | Approach | Complexity |
|---------|----------|------------|
| Merge two sorted lists | Two‑pointer scan | O(n+m) |
| Median of two sorted arrays | Binary search partition | O(log min(n,m)) |
| Longest increasing subsequence | Patience sorting + binary search | O(n log n) |

```java
// Merge two sorted lists
List<Integer> merge(List<Integer> a, List<Integer> b) {
    List<Integer> res = new ArrayList<>();
    int i=0,j=0;
    while(i<a.size() && j<b.size()){
        if(a.get(i)<=b.get(j)){ res.add(a.get(i++)); }
        else{ res.add(b.get(j++)); }
    }
    while(i<a.size()){ res.add(a.get(i++)); }
    while(j<b.size()){ res.add(b.get(j++)); }
    return res;
}

// Median of two sorted arrays
double findMedianSortedArrays(int[] A, int[] B) {
    if(A.length > B.length) return findMedianSortedArrays(B, A);
    int m=A.length, n=B.length;
    int imin=0, imax=m, halfLen=(m+n+1)/2;
    while(imin<=imax){
        int i=(imin+imax)/2;
        int j=halfLen-i;
        if(i< m && B[j-1] > A[i]) imin=i+1;
        else if(i>0 && A[i-1] > B[j]) imax=i-1;
        else {
            int maxLeft = 0;
            if(i==0) maxLeft=B[j-1];
            else if(j==0) maxLeft=A[i-1];
            else maxLeft=Math.max(A[i-1], B[j-1]);

            if((m+n)%2==1) return maxLeft;
            int minRight = 0;
            if(i==m) minRight=B[j];
            else if(j==n) minRight=A[i];
            else minRight=Math.min(A[i], B[j]);

            return (maxLeft + minRight)/2.0;
        }
    }
    throw new IllegalArgumentException();
}

// Longest increasing subsequence
int lengthOfLIS(int[] nums) {
    int[] tails = new int[nums.length];
    int size = 0;
    for(int x: nums){
        int i=0, j=size;
        while(i<j){
            int m=(i+j)/2;
            if(tails[m] < x) i=m+1; else j=m;
        }
        tails[i]=x;
        if(i==size) size++;
    }
    return size;
}
```

