// 1. Merge two CRDT maps
public static Map<String, CrdtValue> mergeMaps(Map<String, CrdtValue> a,
                                               Map<String, CrdtValue> b) {
    Map<String, CrdtValue> res = new HashMap<>(a);
    b.forEach((k, v) -> res.merge(k, v, CrdtValue::merge));
