}

// 2. Compute HLC tick
public static HlcStamp tick(HlcStamp current, long wallClock) {
    long ts = Math.max(current.getTimestamp(), wallClock);
    long counter = (ts == current.getTimestamp()) ? current.getCounter() + 1 : 0;
    return new HlcStamp(ts, counter);
}

// 3. Resolve GCounter conflict
public static int resolveGCounter(int local, int remote) { return Math.max(local, remote); }
