// Consumer side – Axon event sourcing
@Component
public class ReplicationListener {
    private final CRDT<String, String> crdt;
    private final HybridLogicalClock localClock;

    public ReplicationListener(CRDT<String, String> crdt, HybridLogicalClock localClock) {
