@Component
public class ReplicationPipeline {
    private final KafkaTemplate<String, ReplicationEvent> kafka;
    private final ReplicationRepository repo;
    private final CircuitBreaker cb = CircuitBreaker.ofDefaults("replication");

    @EventListener
    public void onEvent(ReplicationEvent event) {
        cb.executeSupplier(() -> {
            kafka.send("replication-topic", event.getKey().toString(), event);
            repo.markAcknowledged(event.getKey());
            return null;
        });
    }
}
