public List<ReplicationEvent> mergeLogs(List<ReplicationEvent> a, List<ReplicationEvent> b) {
    List<ReplicationEvent> merged = new ArrayList<>();
    int i=0,j=0;
    while(i<a.size() && j<b.size()){
        if(a.get(i).getTimestamp().compareTo(b.get(j).getTimestamp())<=0){
            merged.add(a.get(i++));
        }else{
            merged.add(b.get(j++));
        }
    }
    while(i<a.size()) merged.add(a.get(i++));
    while(j<b.size()) merged.add(b.get(j++));
    return merged;
}
