def has_causal_cycle(graph):
    visited, rec = set(), set()
    def dfs(node):
        visited.add(node); rec.add(node)
        for nbr in graph.get(node, []):
            if nbr not in visited and dfs(nbr):
                return True
            if nbr in rec:
                return True
        rec.remove(node); return False
    return any(dfs(n) for n in graph)
