### DSA – Three Java Helpers

```java
// 1. Binary search on sorted HLC list
public static int binarySearchHLC(List<HLC> list, HLC target) {
    int lo = 0, hi = list.size() - 1;
    while (lo <= hi) {
        int mid = (lo + hi) >>> 1;
        int cmp = list.get(mid).compareTo(target);
        if (cmp < 0) lo = mid + 1;
        else if (cmp > 0) hi = mid - 1;
        else return mid;
    }
    return -lo - 1;
}

// 2. Merge two sorted CRDT update streams
public static List<CRDTUpdate> mergeStreams(List<CRDTUpdate> a, List<CRDTUpdate> b) {
    List<CRDTUpdate> out = new ArrayList<>();
    int i = 0, j = 0;
    while (i < a.size() && j < b.size()) {
        if (a.get(i).hlc.compareTo(b.get(j).hlc) <= 0) out.add(a.get(i++));
        else out.add(b.get(j++));
    }
    while (i < a.size()) out.add(a.get(i++));
    while (j < b.size()) out.add(b.get(j++));
    return out;
}

// 3. HLC comparison utility
public static boolean isStale(HLC local, HLC client) {
    return local.compareTo(client) < 0;
}
