### Data‑structures & algorithms (DSA) – three Java solutions

    // 1. Merge two sorted int arrays into a new sorted array
    public static int[] mergeSorted(int[] a, int[] b) {
        int[] out = new int[a.length + b.length];
        int i=0,j=0,k=0;
        while(i<a.length && j<b.length)
            out[k++] = (a[i] <= b[j]) ? a[i++] : b[j++];
        while(i<a.length) out[k++] = a[i++];
        while(j<b.length) out[k++] = b[j++];
        return out;
    }

    // 2. Longest palindrome substring (Manacher’s O(n))
    public static String longestPal(String s) {
        char[] t = ('#' + String.join("#", s.split("")) + "#").toCharArray();
        int[] p = new int[t.length];
        int c=0,r=0,maxLen=0,center=0;
        for(int i=0;i<t.length;i++){
            int mir = 2*c - i;
            if(i<r) p[i]=Math.min(r-i,p[mir]);
            while(i+1+p[i] < t.length && i-1-p[i] >=0 && t[i+1+p[i]]==t[i-1-p[i]]) p[i]++;
            if(i+p[i] > r){ c=i; r=i+p[i]; }
            if(p[i] > maxLen){ maxLen=p[i]; center=i; }
        }
        int start = (center - maxLen)/2;
        return s.substring(start, start+maxLen);
    }

    // 3. Top‑K frequent elements using a min‑heap
    public static List<Integer> topK(int[] nums, int k){
        Map<Integer,Integer> freq = new HashMap<>();
        for(int n:nums) freq.merge(n,1,Integer::sum);
        PriorityQueue<Map.Entry<Integer,Integer>> heap =
            new PriorityQueue<>(Map.Entry.comparingByValue());
        for(var e:freq.entrySet()){
            heap.offer(e);
            if(heap.size()>k) heap.poll();
        }
        List<Integer> res = new ArrayList<>();
        while(!heap.isEmpty()) res.add(heap.poll().getKey());
        Collections.reverse(res);
        return res;
    }

### Python – runnable HLC simulator (ML / AI / Data)

    import time, threading

    class HLC:
        def __init__(self):
            self.physical = int(time.time()*1000)
            self.logical = 0
            self.lock = threading.Lock()
        def tick(self):
            with self.lock:
                now = int(time.time()*1000)
                if now > self.physical:
                    self.physical = now
                    self.logical = 0
                else:
                    self.logical += 1
                return (self.physical, self.logical)
        def merge(self, remote):
            with self.lock:
                now = int(time.time()*1000)
                self.physical = max(self.physical, remote[0], now)
                self.logical = max(self.logical, remote[1]) + (1 if self.physical==remote[0] else 0)
                return (self.physical, self.logical)

    # quick demo
    hlc = HLC()
    print("stamp:", hlc.tick())

