## subgraph Region B

Region B is the counterpart to the write‑optimised Zone A depicted earlier. While Zone A guarantees linearizability for local clients, Region B must reconcile updates that arrive from multiple geo‑distributed masters, apply Hybrid Logical Clock (HLC) timestamps, and merge state using Conflict‑Free Replicated Data Types (CRDTs). The following deep‑dive explains the region‑specific domain model, the Spring‑Boot REST façade, the Axon‑driven command‑event pipeline, resilience mechanisms powered by Resilience4j, and the Kafka consumer that drives eventual consistency across the globe.

### 1. Low‑Level Domain Model for Region B

The model isolates three concerns:

* **Versioning** – HLC encapsulated in `HybridTimestamp`.
* **CRDT payload** – a generic `LWWRegister<T>` (last‑write‑wins) that can be specialised for strings, JSON blobs, or binary blobs.
* **Replication metadata** – `ReplicaId` and `RegionId` for provenance tracking.

```java
public enum RegionId {
    REGION_A, REGION_B, REGION_C
}

public final class ReplicaId {
    private final UUID id;
    public ReplicaId(UUID id) { this.id = Objects.requireNonNull(id); }
    public UUID get() { return id; }
    @Override public boolean equals(Object o) { return (o instanceof ReplicaId r) && r.id.equals(id); }
    @Override public int hashCode() { return id.hashCode(); }
    @Override public String toString() { return id.toString(); }
}

/**
 * Hybrid Logical Clock timestamp – combines physical time with a logical counter.
 */
public final class HybridTimestamp implements Comparable<HybridTimestamp> {
    private final long physical;   // epoch millis
    private final int logical;     // monotonically increasing per node

    private HybridTimestamp(long physical, int logical) {
        this.physical = physical;
        this.logical = logical;
    }

    public static HybridTimestamp now() {
        return new HybridTimestamp(System.currentTimeMillis(), 0);
    }

    public HybridTimestamp tick() {
        return new HybridTimestamp(physical, logical + 1);
    }

    @Override public int compareTo(HybridTimestamp o) {
        int cmp = Long.compare(this.physical, o.physical);
        return (cmp != 0) ? cmp : Integer.compare(this.logical, o.logical);
    }

    @Override public String toString() {
        return physical + ":" + logical;
    }
}

/**
 * Base interface for all CRDT registers used in Region B.
 */
public interface CrdtRegister<T> {
    HybridTimestamp getTimestamp();
    T getValue();
    CrdtRegister<T> merge(CrdtRegister<T> other);
}

/**
 * Last‑Write‑Wins register implementation.
 */
public final class LWWRegister<T> implements CrdtRegister<T> {
    private final HybridTimestamp ts;
    private final T value;

    private LWWRegister(HybridTimestamp ts, T value) {
        this.ts = ts;
        this.value = value;
    }

    public static <T> LWWRegister<T> of(HybridTimestamp ts, T value) {
        return new LWWRegister<>(ts, value);
    }

    @Override public HybridTimestamp getTimestamp() { return ts; }
    @Override public T getValue() { return value; }

    @Override public CrdtRegister<T> merge(CrdtRegister<T> other) {
        return (other.getTimestamp().compareTo(this.ts) > 0) ? other : this;
    }

    @Override public String toString() {
        return "LWWRegister{ts=" + ts + ", value=" + value + '}';
    }
}

/**
 * Aggregate root representing a key‑value entry in Region B.
 */
public abstract class KvEntry {
    protected final String key;
    protected final ReplicaId replicaId;
    protected final RegionId regionId;

    protected KvEntry(String key, ReplicaId replicaId, RegionId regionId) {
        this.key = Objects.requireNonNull(key);
        this.replicaId = Objects.requireNonNull(replicaId);
        this.regionId = Objects.requireNonNull(regionId);
    }

    public String getKey() { return key; }
    public ReplicaId getReplicaId() { return replicaId; }
    public RegionId getRegionId() { return regionId; }
}

/**
 * Concrete entry for string values.
 */
public final class StringKvEntry extends KvEntry {
    private final LWWRegister<String> register;

    public StringKvEntry(String key, ReplicaId replicaId, RegionId regionId,
                         LWWRegister<String> register) {
        super(key, replicaId, regionId);
        this.register = register;
    }

    public LWWRegister<String> getRegister() { return register; }

    public StringKvEntry merge(StringKvEntry other) {
        LWWRegister<String> merged = (LWWRegister<String>) this.register.merge(other.register);
        return new StringKvEntry(key, replicaId, regionId, merged);
    }
}
