### Architecture Pattern – Resilience4j + Axon + Spring Kafka

```java
@Component
@RequiredArgsConstructor
public class CounterService {
    private final KafkaTemplate<String, CounterEvent> kafka;
    private final CounterRepository repo;
    @Retry(name = "counterRetry", fallbackMethod = "fallback")
    @CircuitBreaker(name = "counterCB")
    public Counter apply(String id, OpType op, long delta, HLC ts) {
        Counter curr = repo.find(id).orElse(new Counter(ts, 0));
        Counter updated = (op == OpType.INCREMENT) ?
                new Counter(ts, curr.getValue() + delta) :
                new Counter(ts, curr.getValue() - delta);
        repo.save(id, updated);
        kafka.send("counter-topic", id, new CounterEvent(id, updated));
        return updated;
    }
    private Counter fallback(String id, OpType op, long delta, HLC ts, Throwable t) { return repo.find(id).orElseThrow(); }
}
