```java
// LLD – Read domain
public interface ReadService {
    ReadResponse read(String key, HLC clientHlc);
}

public record ReadRequest(String key, HLC clientHlc) {}
public record ReadResponse(String value, HLC serverHlc) {}

@RestController
@RequestMapping("/api/kv")
@RequiredArgsConstructor
public class KvReadController {
    private final ReadService readService;

    @GetMapping("/{key}")
    public ResponseEntity<ReadResponse> get(
            @PathVariable String key,
            @RequestHeader("X-Client-HLC") String hlcStr) {
        HLC clientHlc = HLC.fromString(hlcStr);
        ReadResponse resp = readService.read(key, clientHlc);
        return ResponseEntity.ok(resp);
    }
}
